module legacy_files;
fn old_read(value:i64) -> i64 { return value+1; }
fn old_write(value:str) -> str { return value; }
fn identity<T:wire>(value:T) -> T { return unwrap(decode_json<T>(encode_json(value))); }
fn main() -> unit !{io} { print(identity(old_read(41))); print(old_write("Я🧠")); }
test fn preserved_test() -> unit { assert(old_read(41)==42); assert(old_write("text")=="text"); }
